# ===================== CLOUD NETWORKING (15) =====================
CLOUD=[
t("aws-vpc","cloud_networking",5,"AWS VPC","intermediate",{"what":"Amazon VPC (Virtual Private Cloud) is an isolated virtual network in AWS where you launch resources. You control IP ranges, subnets, route tables, and gateways.","why":"VPC is the foundation of all AWS networking. Every EC2 instance, RDS database, and Lambda function runs inside a VPC. Understanding VPC design is essential for cloud engineers.","how":"VPC components:\n- CIDR block (e.g., 10.0.0.0/16)\n- Subnets (public + private, across AZs)\n- Internet Gateway (public internet access)\n- NAT Gateway (private subnet outbound)\n- Route Tables (control traffic flow)\n- Security Groups (instance-level firewall)\n- NACLs (subnet-level firewall)","when":"Every AWS deployment needs VPC design. Plan subnets for: public (web), private (app), data (DB), management. Use multiple AZs for HA.","key_concepts":["CIDR block","Public vs Private subnets","Internet Gateway","NAT Gateway","Route Tables","Security Groups vs NACLs","Availability Zones"],"configuration":"# Terraform VPC\nresource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n  enable_dns_hostnames = true\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n  map_public_ip_on_launch = true\n}","troubleshooting":["VPC Flow Logs","Check route tables","Verify Security Group rules","Check NACL rules (stateless!)","Verify IGW attached"]},["subnetting","nat-pat","firewall-fundamentals"],["aws","vpc","cloud","subnets","security-groups"]),
t("aws-security-groups","cloud_networking",5,"AWS Security Groups","beginner",{"what":"Security Groups are virtual firewalls for EC2 instances. They control inbound and outbound traffic at the instance level. They are stateful — return traffic is automatically allowed.","why":"Security Groups are the primary network security control in AWS. Misconfigured SGs (0.0.0.0/0 on SSH) are one of the most common cloud security findings.","how":"Rules specify: Protocol, Port range, Source/Destination (IP or another SG).\n\nKey behaviors:\n- Default: deny all inbound, allow all outbound\n- Stateful: if inbound allowed, response automatically allowed\n- Can reference other SGs (e.g., allow from web-sg to app-sg)\n- Changes take effect immediately","when":"Configure SGs for every resource. Follow least privilege — only allow required ports from required sources. Never use 0.0.0.0/0 for management ports.","key_concepts":["Stateful (vs NACLs which are stateless)","Default deny inbound","Allow all outbound (default)","Reference other SGs","No deny rules (only allow)","Applied at instance level"],"configuration":"# Terraform Security Group\nresource \"aws_security_group\" \"web\" {\n  vpc_id = aws_vpc.main.id\n  \n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n  \n  ingress {\n    from_port       = 22\n    to_port         = 22\n    protocol        = \"tcp\"\n    security_groups = [aws_security_group.bastion.id]\n  }\n}","troubleshooting":["Check inbound rules allow traffic","Verify source IP/SG reference","Remember: no deny rules possible","Check if instance is in correct SG","VPC Flow Logs show denied traffic"]},["aws-vpc","firewall-fundamentals"],["aws","security-groups","firewall","stateful","cloud"]),
t("aws-route-tables","cloud_networking",5,"AWS Route Tables","beginner",{"what":"Route tables control where network traffic is directed within a VPC. Each subnet is associated with a route table that determines how traffic flows.","why":"Without proper route tables, subnets can't reach the internet, other subnets, or on-premises networks. Route tables are how you make subnets 'public' or 'private'.","how":"Each route table has rules:\n- Destination: CIDR block\n- Target: Where to send (IGW, NAT GW, VPC Peering, TGW, local)\n\nPublic subnet: Route to 0.0.0.0/0 → Internet Gateway\nPrivate subnet: Route to 0.0.0.0/0 → NAT Gateway\nLocal route (VPC CIDR → local) is always present and can't be removed.","when":"Configure route tables when: creating subnets, setting up internet access, connecting VPCs, or establishing hybrid connectivity.","key_concepts":["Local route (automatic)","0.0.0.0/0 → IGW (public)","0.0.0.0/0 → NAT GW (private)","Subnet association","Most specific route wins","Main route table (default)"],"configuration":"# Terraform Route Table\nresource \"aws_route_table\" \"public\" {\n  vpc_id = aws_vpc.main.id\n  route {\n    cidr_block = \"0.0.0.0/0\"\n    gateway_id = aws_internet_gateway.main.id\n  }\n}\n\nresource \"aws_route_table_association\" \"public\" {\n  subnet_id      = aws_subnet.public.id\n  route_table_id = aws_route_table.public.id\n}","troubleshooting":["Check subnet association","Verify default route target","Most specific route wins","Check if IGW/NAT GW exists","VPC Flow Logs for routing issues"]},["aws-vpc","subnetting"],["aws","routing","route-table","internet","cloud"]),
t("azure-vnet","cloud_networking",5,"Azure Virtual Network","intermediate",{"what":"Azure VNet is the fundamental building block for private networks in Azure. Similar to AWS VPC — provides isolation, subnetting, and connectivity control.","why":"Every Azure resource that needs networking runs in a VNet. Understanding VNet design, NSGs, and connectivity options is essential for Azure cloud engineers.","how":"VNet components:\n- Address space (CIDR, e.g., 10.0.0.0/16)\n- Subnets (no public/private distinction — use NSGs)\n- NSGs (Network Security Groups — like AWS SGs but stateless at subnet level)\n- Route tables (UDRs — User Defined Routes)\n- VNet Peering (connect VNets)\n- VPN Gateway / ExpressRoute (hybrid)","when":"Every Azure deployment. Design subnets for: web tier, app tier, data tier, management. Use NSGs on every subnet.","key_concepts":["Address space","Subnets","NSGs (Network Security Groups)","UDR (User Defined Routes)","VNet Peering","Service Endpoints","Private Endpoints"],"configuration":"# Azure CLI\naz network vnet create \\\n  --name MyVNet \\\n  --resource-group MyRG \\\n  --address-prefix 10.0.0.0/16 \\\n  --subnet-name WebSubnet \\\n  --subnet-prefix 10.0.1.0/24\n\naz network nsg create \\\n  --name WebNSG \\\n  --resource-group MyRG","troubleshooting":["Check NSG rules (both subnet and NIC level)","Verify effective routes","Network Watcher for diagnostics","Check service endpoints","IP flow verify tool"]},["aws-vpc","subnetting","firewall-fundamentals"],["azure","vnet","cloud","nsg","networking"]),
t("hybrid-connectivity","cloud_networking",5,"Hybrid Cloud Connectivity","advanced",{"what":"Hybrid connectivity connects on-premises networks to cloud VPCs/VNets. Options include VPN (over internet) and dedicated connections (Direct Connect, ExpressRoute).","why":"Most enterprises have existing on-premises infrastructure. Hybrid connectivity enables gradual cloud migration, disaster recovery, and keeping sensitive workloads on-premises.","how":"Options:\n- Site-to-Site VPN: Encrypted tunnel over internet (quick, cheap, limited bandwidth)\n- AWS Direct Connect / Azure ExpressRoute: Dedicated physical connection (expensive, high bandwidth, low latency)\n- Transit Gateway: Hub for connecting multiple VPCs and on-premises\n\nConsiderations: Bandwidth, latency, redundancy, cost, encryption.","when":"Use VPN for: dev/test, low-bandwidth needs, quick setup. Use Direct Connect/ExpressRoute for: production workloads, high bandwidth, low latency requirements.","key_concepts":["Site-to-Site VPN","Direct Connect / ExpressRoute","Transit Gateway","BGP for dynamic routing","Redundancy (dual tunnels)","Encryption requirements"],"configuration":"# AWS Site-to-Site VPN (Terraform)\nresource \"aws_vpn_gateway\" \"main\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_customer_gateway\" \"onprem\" {\n  bgp_asn    = 65000\n  ip_address = \"203.0.113.1\"\n  type       = \"ipsec.1\"\n}","troubleshooting":["Check VPN tunnel status","Verify BGP peering","Check route propagation","Monitor bandwidth utilization","Test failover"]},["aws-vpc","vpn-ipsec","bgp-fundamentals"],["hybrid","vpn","direct-connect","expressroute","cloud"]),
]

# ===================== NETWORK AUTOMATION (15) =====================
AUTO=[
t("python-netmiko","network_automation",6,"Python + Netmiko","intermediate",{"what":"Netmiko is a Python library that simplifies SSH connections to network devices. It handles device-specific quirks (prompts, paging, timing) so you can focus on commands.","why":"Manual CLI configuration doesn't scale. With 100+ devices, automation is essential. Netmiko makes it easy to connect, send commands, and parse output programmatically.","how":"Netmiko workflow:\n1. Define device connection parameters\n2. Establish SSH connection\n3. Send commands (show or config)\n4. Parse output\n5. Disconnect\n\nSupports: Cisco IOS/NX-OS, Juniper, Arista, Palo Alto, and 50+ platforms.","when":"Use Netmiko for: bulk configuration changes, automated backups, compliance checks, information gathering across many devices.","key_concepts":["ConnectHandler","send_command (show)","send_config_set (config mode)","Device types","TextFSM parsing","Exception handling"],"configuration":"from netmiko import ConnectHandler\n\ndevice = {\n    'device_type': 'cisco_ios',\n    'host': '192.168.1.1',\n    'username': 'admin',\n    'password': 'cisco123',\n}\n\nwith ConnectHandler(**device) as conn:\n    output = conn.send_command('show ip int brief')\n    print(output)\n    \n    # Config change\n    commands = ['interface lo0', 'ip address 1.1.1.1 255.255.255.255']\n    conn.send_config_set(commands)","troubleshooting":["Connection timeout → check SSH access","Authentication failed → verify credentials","Command timeout → increase timeout parameter","Wrong device_type → check platform"]},["python-basics"],["netmiko","python","ssh","automation","cisco"]),
t("ansible-network","network_automation",6,"Ansible for Network Automation","intermediate",{"what":"Ansible is an agentless automation tool that uses YAML playbooks to configure network devices. It connects via SSH/NETCONF and executes tasks declaratively.","why":"Ansible provides idempotent, repeatable network configuration. Write once, run on hundreds of devices. No agent installation needed — works with existing SSH access.","how":"Ansible components:\n- Inventory: List of devices\n- Playbook: YAML file defining tasks\n- Modules: cisco.ios.ios_config, junipernetworks.junos.junos_config, etc.\n- Roles: Reusable task collections\n\nExecution: ansible-playbook → connects to devices → executes modules → reports results.","when":"Use Ansible for: standardized configurations, compliance enforcement, bulk changes, network provisioning, and configuration backup.","key_concepts":["Playbooks (YAML)","Inventory","Modules (ios_config, ios_command)","Idempotency","Roles","Jinja2 templates","ansible-vault (secrets)"],"configuration":"# inventory.yml\nall:\n  children:\n    switches:\n      hosts:\n        sw1:\n          ansible_host: 192.168.1.10\n          ansible_network_os: cisco.ios.ios\n\n# playbook.yml\n- name: Configure NTP\n  hosts: switches\n  gather_facts: no\n  tasks:\n    - name: Set NTP server\n      cisco.ios.ios_config:\n        lines:\n          - ntp server 10.0.0.5","troubleshooting":["ansible-playbook -vvv (verbose)","Check SSH connectivity first","Verify ansible_network_os","Use --check for dry run","Check module documentation"]},["python-netmiko"],["ansible","automation","playbook","yaml","idempotent"]),
t("terraform-network","network_automation",6,"Terraform for Network Infrastructure","intermediate",{"what":"Terraform is an Infrastructure as Code (IaC) tool that provisions and manages network infrastructure declaratively. Define desired state, Terraform makes it happen.","why":"Terraform enables version-controlled, repeatable infrastructure. Network changes go through code review, testing, and CI/CD — just like application code.","how":"Terraform workflow:\n1. Write: Define resources in .tf files (HCL)\n2. Plan: terraform plan (preview changes)\n3. Apply: terraform apply (make changes)\n4. State: Terraform tracks current state\n\nProviders: AWS, Azure, GCP, Palo Alto, Cisco, F5, etc.","when":"Use Terraform for: cloud network provisioning (VPCs, subnets, firewalls), firewall rule management, DNS management, and any infrastructure that has an API.","key_concepts":["HCL (HashiCorp Configuration Language)","State file","Plan → Apply workflow","Providers","Modules (reusable)","Remote state (S3, Terraform Cloud)"],"configuration":"# main.tf\nprovider \"aws\" {\n  region = \"us-east-1\"\n}\n\nresource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n  tags = { Name = \"production\" }\n}\n\nresource \"aws_subnet\" \"web\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\n# Commands:\n# terraform init\n# terraform plan\n# terraform apply","troubleshooting":["terraform plan (preview before apply)","terraform state list (check state)","terraform import (import existing)","Check provider documentation","State lock issues → check backend"]},["aws-vpc","azure-vnet"],["terraform","iac","infrastructure","declarative","automation"]),
t("netconf-yang","network_automation",6,"NETCONF and YANG","advanced",{"what":"NETCONF is a network management protocol (RFC 6241) that uses XML over SSH. YANG is the data modeling language that defines the structure of configuration and state data.","why":"CLI scraping is fragile — output format changes break scripts. NETCONF/YANG provides structured, programmatic access to device configuration with transaction support (commit/rollback).","how":"NETCONF operations:\n- get-config: Retrieve configuration\n- edit-config: Modify configuration\n- commit: Apply changes (candidate → running)\n- lock/unlock: Prevent concurrent changes\n\nYANG models define: containers, lists, leaves, types, constraints. Models are vendor-specific or standard (OpenConfig, IETF).","when":"Use NETCONF/YANG for: programmatic configuration management, when you need transactions (commit/rollback), or when working with modern network devices that support it.","key_concepts":["XML-based protocol","SSH transport (port 830)","YANG data models","Candidate vs Running config","Commit/Rollback","OpenConfig models"],"configuration":"# Python ncclient\nfrom ncclient import manager\n\nwith manager.connect(\n    host='192.168.1.1',\n    port=830,\n    username='admin',\n    password='cisco',\n    hostkey_verify=False\n) as m:\n    config = m.get_config(source='running')\n    print(config)","troubleshooting":["Check port 830 (SSH subsystem)","Verify YANG model support","Use pyang to validate models","Check device NETCONF capabilities"]},["python-netmiko","ansible-network"],["netconf","yang","xml","programmatic","structured"]),
t("rest-api-network","network_automation",6,"REST APIs for Network Devices","intermediate",{"what":"Many modern network devices expose REST APIs for programmatic management. Send HTTP requests (GET/POST/PUT/DELETE) to configure and monitor devices.","why":"REST APIs are the standard for modern automation. They're language-agnostic, well-documented, and integrate easily with CI/CD pipelines and orchestration tools.","how":"Common patterns:\n- GET /api/interfaces → list interfaces\n- POST /api/vlans → create VLAN\n- PUT /api/vlans/10 → update VLAN 10\n- DELETE /api/vlans/10 → remove VLAN 10\n\nAuthentication: Token-based, API keys, or OAuth.\nFormat: JSON (usually).","when":"Use REST APIs when: device supports it (Cisco DNA Center, Meraki, Palo Alto, F5), building integrations, or creating custom dashboards.","key_concepts":["HTTP methods (GET/POST/PUT/DELETE)","JSON payloads","Authentication (tokens, API keys)","Status codes (200, 201, 400, 401, 404)","Pagination","Rate limiting"],"configuration":"import requests\n\n# Cisco DNA Center example\nurl = 'https://dnac.example.com/dna/intent/api/v1/network-device'\nheaders = {'X-Auth-Token': token, 'Content-Type': 'application/json'}\n\nresponse = requests.get(url, headers=headers, verify=False)\ndevices = response.json()['response']\n\nfor device in devices:\n    print(f\"{device['hostname']}: {device['managementIpAddress']}\")","troubleshooting":["Check authentication token","Verify API endpoint URL","Check HTTP status code","Review API documentation","Use Postman for testing"]},["python-netmiko"],["api","rest","http","json","programmatic"]),
]

# ===================== MORE FUNDAMENTALS (10) =====================
FUND2=[
t("ipv6-basics","fundamentals",1,"IPv6 Basics","intermediate",{"what":"IPv6 uses 128-bit addresses (vs IPv4's 32-bit), providing virtually unlimited addresses. Format: eight groups of four hex digits separated by colons.","why":"IPv4 addresses are exhausted. IPv6 is the future of networking — already used by major providers. Understanding IPv6 is increasingly required for network engineers.","how":"IPv6 address: 2001:0db8:85a3:0000:0000:8a2e:0370:7334\nShortened: 2001:db8:85a3::8a2e:370:7334\n\nTypes: Global Unicast (public), Link-Local (fe80::), Multicast (ff00::)\nNo broadcast in IPv6 — uses multicast instead.\nNo NAT needed — every device gets a public address.","when":"IPv6 is used alongside IPv4 (dual-stack) in most modern networks. Required for: mobile networks, IoT, and future-proofing.","key_concepts":["128-bit address","No NAT needed","Link-Local (fe80::)","SLAAC (auto-configuration)","Dual-stack","No broadcast (multicast only)"],"configuration":"# Linux\nip -6 addr add 2001:db8::1/64 dev eth0\nip -6 route add default via 2001:db8::ffff\n\n# Cisco\ninterface GigabitEthernet0/0\n ipv6 address 2001:db8::1/64\n ipv6 enable","troubleshooting":["ping6 / ping -6","ip -6 route show","show ipv6 interface","show ipv6 route"]},["ipv4-addressing","subnetting"],["ipv6","addressing","128-bit","future","dual-stack"]),
t("http-https","fundamentals",1,"HTTP/HTTPS","beginner",{"what":"HTTP (Hypertext Transfer Protocol) is the foundation of web communication. HTTPS adds TLS encryption for security. Both use TCP port 80 (HTTP) and 443 (HTTPS).","why":"HTTP/HTTPS is the most common application protocol. Understanding it is essential for web troubleshooting, security (HTTPS enforcement), and application delivery.","how":"HTTP request/response:\n1. Client sends request (GET /page HTTP/1.1)\n2. Server processes request\n3. Server sends response (HTTP/1.1 200 OK + body)\n\nMethods: GET, POST, PUT, DELETE, PATCH\nStatus codes: 2xx (success), 3xx (redirect), 4xx (client error), 5xx (server error)\n\nHTTPS = HTTP + TLS (encryption + certificate verification).","when":"Every web application uses HTTP/HTTPS. Troubleshoot when: pages don't load, certificate errors, redirect loops, or slow page loads.","key_concepts":["Request/Response model","Methods (GET, POST, PUT, DELETE)","Status codes (200, 301, 403, 404, 500)","Headers","TLS/SSL certificates","HTTP/2 and HTTP/3"],"configuration":"# Test HTTP\ncurl -v http://example.com\ncurl -I https://example.com  # Headers only\n\n# Check certificate\nopenssl s_client -connect example.com:443","troubleshooting":["curl -v (verbose output)","Check status codes","Verify certificate validity","Check redirect chains","Browser developer tools → Network tab"]},["tcp-protocol","dns-fundamentals"],["http","https","web","tls","application"]),
t("ssh-protocol","fundamentals",1,"SSH (Secure Shell)","beginner",{"what":"SSH provides encrypted remote access to network devices and servers. It replaces insecure Telnet with strong encryption, authentication, and integrity checking.","why":"SSH is how you manage every Linux server and network device. Understanding SSH keys, tunneling, and configuration is essential for any IT professional.","how":"SSH uses public-key cryptography:\n1. Client connects to server (port 22)\n2. Server presents host key (verify fingerprint)\n3. Key exchange (Diffie-Hellman)\n4. Authentication (password or public key)\n5. Encrypted session established\n\nFeatures: Remote shell, file transfer (SCP/SFTP), port forwarding, X11 forwarding.","when":"Use SSH for: all remote management, file transfers, tunneling, and any time you need encrypted remote access.","key_concepts":["Port 22","Public key authentication","Host key verification","SSH tunneling (-L, -R, -D)","SCP/SFTP (file transfer)","SSH config file (~/.ssh/config)"],"configuration":"# Generate SSH key\nssh-keygen -t ed25519 -C 'user@host'\n\n# Copy key to server\nssh-copy-id user@server\n\n# SSH config (~/.ssh/config)\nHost myserver\n  HostName 192.168.1.10\n  User admin\n  IdentityFile ~/.ssh/id_ed25519","troubleshooting":["ssh -v (verbose for debugging)","Check ~/.ssh/authorized_keys","Verify permissions (700 for .ssh, 600 for keys)","Check sshd_config on server","ssh-keyscan (get host key)"]},["tcp-protocol"],["ssh","remote-access","encryption","keys","management"]),
t("ftp-sftp","fundamentals",1,"FTP/SFTP/SCP","beginner",{"what":"FTP transfers files over the network (insecure, plaintext). SFTP and SCP provide encrypted file transfer over SSH.","why":"File transfer is a basic network operation. Understanding the security differences between FTP (insecure) and SFTP/SCP (encrypted) is important for secure operations.","how":"FTP: Uses TCP ports 20 (data) and 21 (control). Plaintext — passwords visible on network.\nSFTP: File transfer over SSH (port 22). Encrypted.\nSCP: Secure copy over SSH. Simple but less features than SFTP.\n\nAlways prefer SFTP/SCP over FTP in production.","when":"Use SFTP/SCP for all file transfers. Only use FTP for legacy systems that don't support alternatives. Never use FTP for sensitive data.","key_concepts":["FTP active vs passive mode","SFTP (SSH File Transfer Protocol)","SCP (Secure Copy)","Port 21 (FTP) vs 22 (SFTP/SCP)","Anonymous FTP (security risk)","FTPS (FTP over TLS)"],"configuration":"# SCP\nscp file.txt user@server:/path/\nscp -r directory/ user@server:/path/\n\n# SFTP\nsftp user@server\nsftp> put localfile.txt\nsftp> get remotefile.txt","troubleshooting":["Check port connectivity (21 or 22)","FTP passive mode issues with NAT","Verify SSH access for SFTP/SCP","Check file permissions on server"]},["ssh-protocol","tcp-protocol"],["ftp","sftp","scp","file-transfer","secure"]),
t("ntp-protocol","fundamentals",1,"NTP (Network Time Protocol)","beginner",{"what":"NTP synchronizes clocks across network devices. Accurate time is critical for logging, authentication (Kerberos), certificates, and forensics.","why":"If device clocks are wrong: logs are useless for correlation, Kerberos auth fails (5-min tolerance), certificates appear expired, and forensic timelines are unreliable.","how":"NTP uses UDP port 123. Stratum hierarchy:\n- Stratum 0: Atomic clocks, GPS\n- Stratum 1: Directly connected to Stratum 0\n- Stratum 2: Syncs from Stratum 1\n- Stratum 3+: Each level syncs from above\n\nNTP adjusts clock gradually (slew) rather than jumping.","when":"Configure NTP on EVERY network device and server. Use at least 2 NTP sources for redundancy. Critical for: SIEM, Kerberos, PKI, compliance.","key_concepts":["Stratum levels","UDP port 123","Clock slew (gradual adjustment)","Multiple sources for redundancy","Chrony (modern Linux)","Authentication (NTP keys)"],"configuration":"# Cisco\nntp server 10.0.0.5\nntp server 10.0.0.6\n\n# Linux (chrony)\nserver 0.pool.ntp.org iburst\nserver 1.pool.ntp.org iburst\n\n# Verify\nshow ntp status\nchronyc tracking","troubleshooting":["show ntp associations","chronyc sources","ntpq -p","Check UDP 514 connectivity","Verify stratum level"]},["udp-protocol"],["ntp","time","synchronization","logging","kerberos"]),
]

# ===================== MORE ENGINEERING (10) =====================
ENG2=[
t("static-routing","network_engineering",2,"Static Routing","beginner",{"what":"Static routes are manually configured routes that tell a router where to send traffic for specific destinations. They don't change automatically.","why":"Static routes are simple, predictable, and use no bandwidth for routing protocol updates. Used for: default routes, stub networks, and small networks.","how":"A static route specifies:\n- Destination network\n- Next-hop IP or exit interface\n\nThe router checks its routing table for the most specific match and forwards accordingly. Static routes have AD (Administrative Distance) of 1 — preferred over dynamic routes.","when":"Use static routes for: default route to ISP, small networks (<5 routers), stub networks with single exit, and backup routes (floating static).","key_concepts":["Next-hop vs exit interface","Administrative Distance (AD=1)","Default route (0.0.0.0/0)","Floating static (higher AD for backup)","Recursive lookup","Directly connected"],"configuration":"! Default route\nip route 0.0.0.0 0.0.0.0 203.0.113.1\n\n! Specific network\nip route 10.0.0.0 255.255.255.0 192.168.1.2\n\n! Floating static (backup, AD=200)\nip route 10.0.0.0 255.255.255.0 192.168.2.2 200","troubleshooting":["show ip route static","show ip route <destination>","Verify next-hop is reachable","Check for recursive routing","ping next-hop"]},["ospf-fundamentals","ipv4-addressing"],["static","routing","default-route","manual","simple"]),
t("eigrp-basics","network_engineering",2,"EIGRP Basics","intermediate",{"what":"EIGRP (Enhanced Interior Gateway Routing Protocol) is a Cisco advanced distance-vector routing protocol. It uses DUAL algorithm for fast convergence and supports unequal-cost load balancing.","why":"EIGRP is widely used in Cisco environments. It's simpler to configure than OSPF, converges faster, and supports unequal-cost load balancing (unique feature).","how":"EIGRP uses:\n- Successor: Best route (in routing table)\n- Feasible Successor: Backup route (pre-calculated)\n- DUAL algorithm: Guarantees loop-free paths\n- Composite metric: Bandwidth + Delay (default)\n\nIf successor fails, feasible successor is instantly promoted — no recalculation needed.","when":"Use EIGRP in Cisco-only environments where simplicity and fast convergence are priorities. Not suitable for multi-vendor networks (use OSPF instead).","key_concepts":["DUAL algorithm","Successor / Feasible Successor","Composite metric (BW + Delay)","Feasibility Condition","Unequal-cost load balancing (variance)","Named EIGRP (modern config)"],"configuration":"! Classic EIGRP\nrouter eigrp 100\n network 10.0.0.0\n network 192.168.1.0\n no auto-summary\n!\n! Named EIGRP (modern)\nrouter eigrp ENTERPRISE\n address-family ipv4 unicast autonomous-system 100\n  network 10.0.0.0 0.0.0.255\n  af-interface default\n   passive-interface","troubleshooting":["show ip eigrp neighbors","show ip eigrp topology","show ip route eigrp","debug eigrp packets"]},["ospf-fundamentals","static-routing"],["eigrp","routing","cisco","dual","fast-convergence"]),
t("mpls-basics","network_engineering",2,"MPLS Basics","advanced",{"what":"MPLS (Multiprotocol Label Switching) forwards packets using labels instead of IP lookups. It creates Label Switched Paths (LSPs) through the network for faster forwarding and traffic engineering.","why":"MPLS enables: VPN services (L3VPN, L2VPN), traffic engineering, fast failover, and QoS. It's the backbone technology for service provider networks.","how":"MPLS process:\n1. Ingress router (LER) adds label to packet\n2. Core routers (LSR) swap labels and forward\n3. Egress router (LER) removes label and routes normally\n\nLabel Distribution Protocol (LDP) distributes labels between routers. Labels are 32-bit, inserted between L2 and L3 headers.","when":"MPLS is used by service providers and large enterprises for: WAN connectivity, VPN services, traffic engineering, and fast reroute.","key_concepts":["Labels (32-bit)","LSP (Label Switched Path)","LER (Label Edge Router)","LSR (Label Switch Router)","LDP (Label Distribution Protocol)","Push/Swap/Pop operations"],"configuration":"! Enable MPLS\nmpls ip\nmpls label protocol ldp\n!\ninterface GigabitEthernet0/0\n mpls ip\n!\n! Verify\nshow mpls interfaces\nshow mpls ldp neighbor\nshow mpls forwarding-table","troubleshooting":["show mpls ldp neighbor","show mpls forwarding-table","show mpls interfaces","debug mpls ldp","traceroute with MPLS labels"]},["ospf-fundamentals","bgp-fundamentals"],["mpls","labels","service-provider","vpn","traffic-engineering"]),
t("vxlan-basics","network_engineering",2,"VXLAN Basics","advanced",{"what":"VXLAN (Virtual Extensible LAN) extends Layer 2 networks over Layer 3 infrastructure using UDP encapsulation. It supports up to 16 million segments (vs VLAN's 4096 limit).","why":"Traditional VLANs are limited to 4096 IDs and can't span L3 boundaries. VXLAN solves both problems — essential for data center fabrics and multi-tenant environments.","how":"VXLAN encapsulates L2 frames in UDP (port 4789):\n- Original frame → VXLAN header (VNI) → UDP → IP → Outer Ethernet\n\nVTEP (VXLAN Tunnel Endpoint): Device that encapsulates/decapsulates.\nVNI (VXLAN Network Identifier): 24-bit ID (16M segments).\nBGP EVPN: Control plane for VXLAN (replaces flood-and-learn).","when":"Use VXLAN in: data center fabrics (leaf-spine), multi-tenant environments, DCI (Data Center Interconnect), and anywhere you need L2 extension over L3.","key_concepts":["VNI (24-bit, 16M segments)","VTEP (Tunnel Endpoint)","UDP port 4789","BGP EVPN (control plane)","Leaf-Spine architecture","Overlay/Underlay"],"configuration":"! NX-OS VXLAN\nfeature nv overlay\nfeature vn-segment-vlan-based\n!\nvlan 100\n vn-segment 10100\n!\ninterface nve1\n source-interface loopback0\n member vni 10100\n  mcast-group 239.1.1.1","troubleshooting":["show nve peers","show nve vni","show vxlan interface","show bgp l2vpn evpn"]},["vlans","ospf-fundamentals"],["vxlan","overlay","data-center","fabric","scalability"]),
t("sd-wan","network_engineering",2,"SD-WAN Basics","intermediate",{"what":"SD-WAN (Software-Defined WAN) separates the control plane from the data plane in WAN networks. It enables centralized management, application-aware routing, and use of multiple transport types.","why":"Traditional WAN (MPLS) is expensive and inflexible. SD-WAN uses cheaper internet links, provides application-level policies, and enables rapid deployment of new sites.","how":"SD-WAN architecture:\n- Orchestrator: Central management/policy\n- Controller: Control plane (routing decisions)\n- Edge devices: Data plane (at each site)\n\nFeatures: Application-aware routing, link quality monitoring, automatic failover, zero-touch provisioning, encryption over any transport.","when":"Use SD-WAN for: multi-site WAN, replacing expensive MPLS, application-based routing, and when you need centralized WAN management.","key_concepts":["Centralized management","Application-aware routing","Multiple transports (MPLS + Internet)","Zero-touch provisioning","Encryption","SLA-based path selection"],"configuration":"# Conceptual (varies by vendor)\n# Cisco SD-WAN (vManage)\n# Policy: Route Office365 via Internet\n# Policy: Route SAP via MPLS\n# Policy: Failover to backup if latency > 100ms","troubleshooting":["Check tunnel status","Verify application classification","Monitor link SLA metrics","Check policy application","Review orchestrator dashboard"]},["vpn-ipsec","bgp-fundamentals","qos-basics"],["sd-wan","wan","software-defined","application-aware","centralized"]),
]

